INSERT INTO usuario (nombre, apellido, correo, contrasena, fecha_registro) VALUES ('Equipo', 'BuildZone', 'equipo@buildzone.com', '$2a$10$WjU6k5mrx/WP1UoI623.y.gKJLzIoYSywTvIyN5GEDte7ek9ztIhW', '2025-01-15 09:00:00');
INSERT INTO noticia (id_usuario, titulo, categoria, resumen, contenido, fecha_publicacion) VALUES ((SELECT id_usuario FROM usuario WHERE correo = 'equipo@buildzone.com'), 'Cómo elegir el mejor procesador para tu PC en 2025', 'Guías', 'Antes de comprar un procesador define primero para qué lo vas a usar: gaming, edición de video o trabajo de oficina.', 'Antes de comprar un procesador define primero para qué lo vas a usar: gaming, edición de video o trabajo de oficina. Compara núcleos, hilos y velocidad, y no olvides revisar que sea compatible con tu placa madre antes de decidir.', '2025-02-10 10:00:00');
INSERT INTO noticia (id_usuario, titulo, categoria, resumen, contenido, fecha_publicacion) VALUES ((SELECT id_usuario FROM usuario WHERE correo = 'equipo@buildzone.com'), 'Guía para armar tu PC paso a paso sin errores', 'Tutorial', 'Arma tu PC en orden: primero el procesador y la RAM sobre la placa madre, luego móntala en el gabinete, conecta la fuente de poder y por último la tarjeta gráfica.', 'Arma tu PC en orden: primero el procesador y la RAM sobre la placa madre, luego móntala en el gabinete, conecta la fuente de poder y por último la tarjeta gráfica. Revisa cada conexión antes de encender el equipo por primera vez.', '2025-03-18 10:00:00');
INSERT INTO noticia (id_usuario, titulo, categoria, resumen, contenido, fecha_publicacion) VALUES ((SELECT id_usuario FROM usuario WHERE correo = 'equipo@buildzone.com'), 'Nuevas GPUs lanzadas en 2025: análisis completo', 'Novedades', 'Este año llegaron tarjetas gráficas con mejoras notables en eficiencia energética y trazado de rayos.', 'Este año llegaron tarjetas gráficas con mejoras notables en eficiencia energética y trazado de rayos. Aquí en BuildZone puedes comparar las especificaciones y precios de los modelos más recientes en la sección de Comparador.', '2025-05-06 10:00:00');
INSERT INTO noticia (id_usuario, titulo, categoria, resumen, contenido, fecha_publicacion) VALUES ((SELECT id_usuario FROM usuario WHERE correo = 'equipo@buildzone.com'), 'RAM: ¿cuánta necesitas y qué velocidad elegir?', 'Guías', 'Para uso general 16GB son suficientes, pero si editas video o usas máquinas virtuales, considera 32GB o más.', 'Para uso general 16GB son suficientes, pero si editas video o usas máquinas virtuales, considera 32GB o más. La velocidad en MHz también influye en el rendimiento, especialmente en procesadores AMD.', '2025-06-24 10:00:00');
INSERT INTO noticia (id_usuario, titulo, categoria, resumen, contenido, fecha_publicacion) VALUES ((SELECT id_usuario FROM usuario WHERE correo = 'equipo@buildzone.com'), 'Refrigeración líquida vs aire: cuál conviene más', 'Tutorial', 'La refrigeración por aire es más económica y fácil de mantener, mientras que la líquida ofrece mejores temperaturas en procesadores de alto rendimiento.', 'La refrigeración por aire es más económica y fácil de mantener, mientras que la líquida ofrece mejores temperaturas en procesadores de alto rendimiento. La elección depende de tu presupuesto y de cuánto exijas a tu equipo.', '2025-08-12 10:00:00');
INSERT INTO noticia (id_usuario, titulo, categoria, resumen, contenido, fecha_publicacion) VALUES ((SELECT id_usuario FROM usuario WHERE correo = 'equipo@buildzone.com'), 'AMD vs Intel en 2025: ¿quién gana en relación precio-rendimiento?', 'Comparativas', 'AMD suele destacar en relación precio-rendimiento para gaming, mientras que Intel mantiene ventaja en tareas de un solo núcleo.', 'AMD suele destacar en relación precio-rendimiento para gaming, mientras que Intel mantiene ventaja en tareas de un solo núcleo. Usa el Comparador de BuildZone para ver las estadísticas lado a lado antes de decidir.', '2025-10-01 10:00:00');
